/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Platform self-check v1: infra / gateway golden / streaming / channels / data. */
const startedAt = Date.now();
const AUTH = 'Bea' + 'rer ' + ($env.CHAT_API_KEY || '');
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const call = async (method, url, opts) => {
  try { const data = await this.helpers.httpRequest({ method, url, timeout: (opts && opts.timeout) || 20000, ...opts }); return { ok: true, status: 200, data }; }
  catch (e) { const status = (e && (e.httpCode || e.statusCode || (e.response && e.response.status))) || 0; return { ok: false, status, error: String((e && e.message) || e).slice(0, 180) }; }
};
let source = 'schedule';
try { $('Webhook Run').first(); source = 'manual'; } catch (e) {}
const checks = [];
const add = async (group, name, fn) => {
  const t0 = Date.now();
  let ok = false, warn = false, detail = '';
  try {
    const r = await fn();
    ok = r === true || !!(r && r.ok === true);
    warn = !!(r && r.warn);
    detail = (r && r.detail) || (ok ? 'ok' : String((r && r.reason) || r));
  } catch (e) { detail = String((e && e.message) || e).slice(0, 200); }
  checks.push({ group, name, ok: ok || warn, warn, detail: String(detail).slice(0, 240), ms: Date.now() - t0 });
};

await add('infra', 'n8n healthz', async () => { const r = await call('GET', 'http://localhost:5678/healthz'); return r.ok ? { ok: true, detail: 'http 200' } : { ok: false, reason: r.error }; });
await add('infra', 'lobechat up', async () => { const r = await call('GET', 'http://lobechat:3210/'); return r.ok ? { ok: true, detail: 'reachable' } : { ok: false, reason: r.error }; });
await add('infra', 'console up', async () => { const r = await call('GET', 'http://host.docker.internal:3000/'); return r.ok ? { ok: true, detail: 'reachable' } : { ok: false, reason: r.error }; });
await add('infra', 'minio health', async () => { const r = await call('GET', 'http://minio:9000/minio/health/live'); return r.ok ? { ok: true } : { ok: false, reason: r.error }; });
await add('infra', 'searxng up', async () => { const r = await call('GET', 'http://searxng:8080/'); return r.ok ? { ok: true } : { ok: false, reason: r.error }; });
await add('infra', 'stream-bridge healthz', async () => { const r = await call('GET', 'http://stream-bridge:3211/healthz'); return r.ok && r.data && r.data.ok ? { ok: true, detail: 'upstream=' + r.data.upstream } : { ok: false, reason: r.error || 'not ok' }; });
await add('infra', 'stream-bridge voice', async () => { const r = await call('GET', 'http://stream-bridge:3211/healthz'); return r.ok && r.data && r.data.voice === true ? { ok: true, detail: 'voice=true' } : { ok: false, reason: 'voice flag missing' }; });
await add('infra', 'n8n api (key)', async () => { const r = await call('GET', 'http://localhost:5678/api/v1/workflows?limit=1', { headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY } }); return r.ok && r.data && Array.isArray(r.data.data) ? { ok: true } : { ok: false, reason: r.error || 'bad payload' }; });

await add('gateway', 'chat simple', async () => { const r = await call('POST', 'http://localhost:5678/webhook/v1/chat/completions', { headers: { 'Content-Type': 'application/json', Authorization: AUTH, 'x-session-id': 'selfcheck', 'x-client': 'selfcheck' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: '请一字不改地复制输出以下内容，不要添加任何其他字符：自检通过' }], stream: false }, timeout: 60000 }); const c = r.ok && r.data && r.data.choices && r.data.choices[0] && r.data.choices[0].message && r.data.choices[0].message.content; return c && String(c).includes('自检通过') ? { ok: true, detail: String(c).slice(0, 40) } : { ok: false, reason: (r.error || 'reply=' + String(c).slice(0, 60)) }; });
await add('gateway', 'chat tool round', async () => { const r = await call('POST', 'http://localhost:5678/webhook/v1/chat/completions', { headers: { 'Content-Type': 'application/json', Authorization: AUTH, 'x-session-id': 'selfcheck', 'x-client': 'selfcheck' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: '平台现在怎么样？只给一句结论' }], stream: false }, timeout: 90000 }); const c = String((r.data && r.data.choices && r.data.choices[0] && r.data.choices[0].message && r.data.choices[0].message.content) || ''); const rounds = r.data && r.data.tool_rounds; return r.ok && /(错误率|成功率|对话)/.test(c) ? { ok: true, detail: 'rounds=' + rounds + ' | ' + c.slice(0, 50) } : { ok: false, reason: (r.error || 'reply=' + c.slice(0, 80)) }; });
await add('gateway', 'auth negative 401', async () => { try { await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/v1/chat/completions', headers: { 'Content-Type': 'application/json' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: 'x' }] }, timeout: 15000 }); return { ok: false, reason: 'unexpected success' }; } catch (e) { const s = (e && (e.httpCode || e.statusCode || (e.response && e.response.status))) || 0; const msg = String((e && e.message) || ''); const is401 = s === 401 || /401/.test(msg); return is401 ? { ok: true, detail: 'rejected (status=' + (s || 'from-message') + ')' } : { ok: false, reason: 'expected 401, got ' + (s || msg.slice(0, 60)) }; } });

await add('stream', 'bridge sse passthrough', async () => { const t0 = Date.now(); const r = await call('POST', 'http://stream-bridge:3211/v1/chat/completions', { headers: { 'Content-Type': 'application/json', Authorization: AUTH, 'x-session-id': 'selfcheck', 'x-client': 'selfcheck' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: '用四个字打招呼' }], stream: true }, timeout: 60000, responseType: 'text' }); const b = typeof r.data === 'string' ? r.data : JSON.stringify(r.data || ''); const ok = r.ok && b.includes('[DONE]') && b.includes('content'); return ok ? { ok: true, detail: 'ms=' + (Date.now() - t0) + ' chunks~' + (b.split('data:').length - 1) } : { ok: false, reason: (r.error || 'body=' + b.slice(0, 80)) }; });
await add('stream', 'bridge tool fallback', async () => { const t0 = Date.now(); const r = await call('POST', 'http://stream-bridge:3211/v1/chat/completions', { headers: { 'Content-Type': 'application/json', Authorization: AUTH, 'x-session-id': 'selfcheck', 'x-client': 'selfcheck' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: '平台现在怎么样？一句话' }], stream: true }, timeout: 150000, responseType: 'text' }); const b = typeof r.data === 'string' ? r.data : JSON.stringify(r.data || ''); const ok = r.ok && b.includes('[DONE]') && /(错误率|成功率|对话)/.test(b); return ok ? { ok: true, detail: 'ms=' + (Date.now() - t0) } : { ok: false, reason: (r.error || 'fallback content missing') }; });
await add('stream', 'bridge non-stream proxy', async () => { const r = await call('POST', 'http://stream-bridge:3211/v1/chat/completions', { headers: { 'Content-Type': 'application/json', Authorization: AUTH, 'x-session-id': 'selfcheck', 'x-client': 'selfcheck' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'user', content: '回复：OK' }], stream: false }, timeout: 60000 }); const c = String((r.data && r.data.choices && r.data.choices[0] && r.data.choices[0].message && r.data.choices[0].message.content) || ''); return r.ok && c.length > 0 ? { ok: true, detail: c.slice(0, 30) } : { ok: false, reason: r.error || 'empty' }; });

await add('channel', 'notify configured', async () => { const r = await call('GET', 'http://localhost:5678/webhook/admin/alerts', { headers: { Authorization: AUTH } }); const d = r.data && r.data.delivery; return r.ok && d && d.configured ? { ok: true, detail: 'format=' + d.format } : { ok: false, reason: r.error || 'not configured' }; });
await add('channel', 'tg bridge state', async () => { const list = await api('GET', '/data-tables', { limit: 100 }); const id = ((list.data || []).find((t) => t.name === 'telegram_state') || {}).id; if (!id) return { ok: false, reason: 'no table' }; const rows = await api('GET', '/data-tables/' + id + '/rows', { limit: 10 }); const has = (rows.data || []).some((x) => x.key === 'last_update_id'); return has ? { ok: true, detail: 'offset row present' } : { ok: false, reason: 'offset missing' }; });
await add('channel', 'reminders api', async () => { const r = await call('GET', 'http://localhost:5678/webhook/admin/reminders', { headers: { Authorization: AUTH } }); return r.ok && r.data && r.data.ok ? { ok: true, detail: 'pending=' + r.data.pending_count } : { ok: false, reason: r.error || 'bad payload' }; });

await add('data', 'backup heartbeat fresh', async () => { const list = await api('GET', '/data-tables', { limit: 100 }); const id = ((list.data || []).find((t) => t.name === 'heartbeats') || {}).id; if (!id) return { ok: false, reason: 'no table' }; const rows = await api('GET', '/data-tables/' + id + '/rows', { limit: 50 }); const bks = (rows.data || []).filter((x) => x.job === 'backup').sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt)); if (!bks.length) return { ok: false, reason: 'no backup heartbeat yet' }; const ageH = (Date.now() - Date.parse(bks[0].createdAt)) / 3600000; const detail = 'age=' + Math.round(ageH * 10) / 10 + 'h ok=' + bks[0].ok; if (bks[0].ok !== 1) return { ok: false, reason: detail + ' (last backup reported failure)' }; if (ageH < 30) return { ok: true, detail }; if (ageH < 40) return { ok: true, warn: true, detail: detail + ' (stale)' }; return { ok: false, reason: detail }; });
await add('data', 'overview sanity', async () => { const r = await call('GET', 'http://localhost:5678/webhook/admin/overview', { headers: { Authorization: AUTH } }); const d = r.data || {}; const ok = r.ok && d.chat_24h && typeof d.chat_24h.total === 'number' && d.delivery && d.kb && !d.kb.error; return ok ? { ok: true, detail: 'chats=' + d.chat_24h.total + ' rate=' + d.chat_24h.error_rate } : { ok: false, reason: r.error || 'shape mismatch' }; });
await add('data', 'stats api', async () => { const r = await call('GET', 'http://localhost:5678/webhook/v1/stats/executions', { headers: { Authorization: AUTH } }); return r.ok && r.data && r.data.totals ? { ok: true, detail: 'total=' + r.data.totals.total } : { ok: false, reason: r.error || 'bad payload' }; });
await add('data', 'messages store readable', async () => { const list = await api('GET', '/data-tables', { limit: 100 }); const id = ((list.data || []).find((t) => t.name === 'chat_messages') || {}).id; if (!id) return { ok: false, reason: 'no table' }; const rows = await api('GET', '/data-tables/' + id + '/rows', { limit: 2 }); return Array.isArray(rows.data) ? { ok: true, detail: 'read ok' } : { ok: false, reason: 'bad read' }; });
await add('data', 'todos api', async () => { const r = await call('GET', 'http://localhost:5678/webhook/admin/todos', { headers: { Authorization: AUTH } }); return r.ok && r.data && typeof r.data.open_count === 'number' ? { ok: true, detail: 'open=' + r.data.open_count + ' overdue=' + r.data.overdue_count } : { ok: false, reason: r.error || 'bad payload' }; });
await add('data', 'memory api', async () => { const r = await call('POST', 'http://localhost:5678/webhook/internal/memory', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { action: 'retrieve', text: 'selfcheck probe' }, timeout: 30000 }); return r.ok && r.data && r.data.ok === true ? { ok: true, detail: 'lobe_refs=' + (r.data.lobe_count || 0) } : { ok: false, reason: r.error || 'bad payload' }; });
await add('data', 'weekly review dry', async () => { const r = await call('POST', 'http://localhost:5678/webhook/admin/weekly-review/run', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { dry: true }, timeout: 120000 }); return r.ok && r.data && r.data.ok === true ? { ok: true, detail: 'chars=' + (r.data.chars || 0) } : { ok: false, reason: r.error || 'bad payload' }; });
await add('infra', 'mcp tools/list', async () => { const r = await call('POST', 'http://localhost:5678/webhook/mcp', { headers: { 'Content-Type': 'application/json', Authorization: ['Bea', 'rer '].join('') + ($env.MCP_API_KEY || ''), 'Mcp-Method': 'tools/list' }, body: { jsonrpc: '2.0', id: 1, method: 'tools/list' }, timeout: 30000 }); const n = r.data && r.data.result && Array.isArray(r.data.result.tools) ? r.data.result.tools.length : 0; return r.ok && n >= 12 ? { ok: true, detail: 'tools=' + n } : { ok: false, reason: r.error || ('tools=' + n) }; });
await add('data', 'workflow tools api', async () => { const r = await call('POST', 'http://localhost:5678/webhook/admin/tools', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { action: 'list' }, timeout: 30000 }); return r.ok && r.data && r.data.ok === true && Array.isArray(r.data.tools) ? { ok: true, detail: 'tools=' + r.data.tools.length } : { ok: false, reason: r.error || 'bad payload' }; });
await add('data', 'people directory', async () => {
await add('data', 'todos ownership', async () => {
await add('data', 'escalation ready', async () => {
await add('data', 'weekly team view', async () => {
await add('data', 'delegation view', async () => {
  const r = await call('GET', 'http://localhost:5678/webhook/admin/delegation', { headers: { Authorization: AUTH }, timeout: 30000 });
  const d = r.data || {};
  const t = d.totals || {};
  const ok = r.ok && d.ok === true && typeof t.assigned_open === 'number' && typeof t.awaiting_ack === 'number' && Array.isArray(d.people);
  return ok ? { ok: true, detail: 'assigned=' + t.assigned_open + ' overdue=' + t.overdue + ' people=' + d.people.length } : { ok: false, reason: r.error || 'shape mismatch' };
});
  const list = await api('GET', '/data-tables', { limit: 100 });
  const wid = ((list.data || []).find((t) => t.name === 'weekly_reviews') || {}).id;
  if (!wid) return { ok: false, reason: 'weekly_reviews table missing' };
  const cols = ((await api('GET', '/data-tables/' + wid + '/columns')) || []).map((c) => c.name);
  if (cols.indexOf('scope') < 0 || cols.indexOf('people_count') < 0) return { ok: false, reason: 'scope/people_count columns missing' };
  const r = await call('POST', 'http://localhost:5678/webhook/admin/weekly-review/run', { headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { dry: true, scope: 'team' }, timeout: 120000 });
  const d = r.data || {};
  const hasTeam = typeof d.content === 'string' && d.content.indexOf('【团队】') >= 0;
  return r.ok && d.ok === true && d.scope === 'team' && hasTeam ? { ok: true, detail: 'people=' + (d.people_count || 0) + ' chars=' + (d.chars || 0) } : { ok: false, reason: r.error || ('scope=' + d.scope + ' teamBlock=' + hasTeam) };
});
  const list = await api('GET', '/data-tables', { limit: 100 });
  const tid = ((list.data || []).find((t) => t.name === 'todos') || {}).id;
  const pid = ((list.data || []).find((t) => t.name === 'people') || {}).id;
  if (!tid || !pid) return { ok: false, reason: 'todos/people table missing' };
  const cols = ((await api('GET', '/data-tables/' + tid + '/columns')) || []).map((c) => c.name);
  const need = ['owner_ref', 'ack_at', 'remind_count', 'last_remind_at', 'escalated'];
  const missing = need.filter((n) => cols.indexOf(n) < 0);
  return missing.length === 0 ? { ok: true, detail: 'columns ok' } : { ok: false, reason: 'missing columns: ' + missing.join(',') };
});
  const base = { headers: { Authorization: AUTH }, timeout: 20000 };
  const all = await call('GET', 'http://localhost:5678/webhook/admin/todos', base);
  const mine = await call('GET', 'http://localhost:5678/webhook/admin/todos?owner=mine', base);
  const okAll = all.ok && all.data && all.data.ok === true && typeof all.data.assigned_count === 'number';
  const okMine = mine.ok && mine.data && mine.data.ok === true && mine.data.owner_filter === 'mine';
  const ppl = (all.data && all.data.people) || [];
  return okAll && okMine && ppl.length > 0 ? { ok: true, detail: 'assigned=' + all.data.assigned_count + ' mine=' + ((mine.data.open || []).length) + ' people=' + ppl.length } : { ok: false, reason: (!okAll ? 'list bad' : !okMine ? 'owner filter bad' : 'people directory empty') };
});
  const r = await call('GET', 'http://localhost:5678/webhook/admin/people', { headers: { Authorization: AUTH }, timeout: 20000 });
  const d = r.data || {};
  const withChannel = (d.people || []).filter((p) => { try { const c = JSON.parse(p.channels || '{}'); return Object.values(c).some((v) => v); } catch (e) { return false; } }).length;
  return r.ok && d.ok === true && typeof d.count === 'number' ? { ok: true, detail: 'people=' + d.count + ' with_channel=' + withChannel } : { ok: false, reason: r.error || 'bad payload' };
});

const failed = checks.filter((c) => !c.ok);
const warned = checks.filter((c) => c.ok && c.warn);
const passed = checks.filter((c) => c.ok && !c.warn);
const duration = Date.now() - startedAt;
const checkedAt = new Date().toISOString();
let persisted = false;
try {
  const list = await api('GET', '/data-tables', { limit: 100 });
  const runsId = ((list.data || []).find((t) => t.name === 'selfcheck_runs') || {}).id;
  if (runsId) {
    await api('POST', '/data-tables/' + runsId + '/rows', null, { data: [{ source, total: checks.length, passed: passed.length, failed: failed.length, warned: warned.length, duration_ms: duration, checked_at: checkedAt, report: JSON.stringify({ checks }).slice(0, 18000) }] });
    const back = await api('GET', '/data-tables/' + runsId + '/rows', { limit: 1 });
    persisted = Array.isArray(back.data) && back.data.length > 0;
  }
} catch (e) {}
if (failed.length && persisted) {
  const msg = '自检未通过（' + failed.length + '/' + checks.length + '）：' + failed.map((f) => f.name).join('、');
  await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/internal/notify', headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { kind: '自检', message: msg }, timeout: 20000 }).catch(() => {});
}
return [{ json: { ok: true, source, total: checks.length, passed: passed.length, failed: failed.length, warned: warned.length, duration_ms: duration, persisted, failures: failed.map((f) => f.name), warnings: warned.map((w) => w.name) } }];
